// USBHost TinyUSB examples cover HID, CDC serial, and MSC.
// Ethernet adapters and cameras need a matching class driver.
// Confirm the USB class descriptor before selecting hardware.
void setup() {
  Serial.begin(115200);
  if (!USBHost.begin()) {
    Serial.println("Check OTG board setup and host VBUS power");
  }
}

void loop() {
  USBHost.task();  // Dispatch supported host-class events.
}
